// HCDEV DERIVED_HINT.EMAILPSWD.SavePreChange, definition ID 5529.
export const source = "import PT_MCF_MAIL:*;\n\nDeclare Function UpdateSystemVersions PeopleCode FUNCLIB_PTSEC.OPRID FieldFormula;\nDeclare Function UpdatePSLOCK PeopleCode FUNCLIB_PTSEC.OPRID FieldFormula;\nDeclare Function ResetPassword PeopleCode FUNCLIB_PTSEC.OPERPSWD FieldFormula;\n\nComponent boolean &bUPMUpdated;\nComponent Record &RecPSOPRDEFN, &RecPSUSERATTR, &RecPSSECOPTIONS, &RecPSPSWDEMAIL_FAIL, &RecPSPSWDEMAIL_PSWD;\nLocal datetime &currDateTime, &calcDateTime;\n\n&bUPMUpdated = False;\n\nrem verify that they have access to have a password emailed;\n&PASSWORDSEND = 0;\n&RECA = CreateRecord(Record.PSUSERCLASSVW);\n&SQL = CreateSQL(\"%SELECTALL(:1) WHERE OPRID = :2\", &RECA, DERIVED_HINT.OPRID);\nWhile (&SQL.Fetch(&RECA)) And\n      (&PASSWORDSEND = 0);\n   &CLASS = &RECA.CLASSID.VALUE;\n   SQLExec(\"SELECT ALLOWPSWDEMAIL FROM PSCLASSDEFN WHERE CLASSID = :1\", &CLASS, &PASSWORDSEND);\nEnd-While;\n&SQL.CLOSE();\n\n\n&currDateTime = %Datetime;\nIf All(&RecPSUSERATTR.LASTUPDDTTM.Value) Then\n   &calcDateTime = AddToDateTime(&RecPSUSERATTR.LASTUPDDTTM.Value, 0, 0, 0, 0, 0, &RecPSSECOPTIONS.PT_HINTDELAY.Value);\nElse\n   &calcDateTime = &currDateTime;\nEnd-If;\n\n\nIf &PASSWORDSEND <> 0 And\n      All(&RecPSOPRDEFN.EMAILID.Value) And\n      All(&RecPSPSWDEMAIL_PSWD.EMAILTEXT.Value) And\n      All(&RecPSUSERATTR.HINT_RESPONSE.Value) Then\n   \n   rem verify response matches;\n   If DERIVED_HINT.HINT_RESPONSE <> &RecPSUSERATTR.HINT_RESPONSE.Value Or\n         (&currDateTime < &calcDateTime) Then\n      If All(&RecPSPSWDEMAIL_FAIL.EMAILTEXT.Value) Then\n         &EMAIL_TEXT = &RecPSPSWDEMAIL_FAIL.EMAILTEXT.Value\n      Else\n         &EMAIL_TEXT = MsgGetExplainText(48, 201, \"Message not found\");\n      End-If;\n   Else\n      rem their response is correct;\n      rem GENERATE RANDOM PASSWORD;\n      &pswd = ResetPassword();\n      &RecPSOPRDEFN.OPERPSWDSALT.Value = \"\";\n      &RecPSOPRDEFN.PTOPERPSWDV2.Value = \"\";\n      &RecPSOPRDEFN.PTOPERPSWDV2.Value = HashWithSalt(&pswd, &newsalt);\n      &RecPSOPRDEFN.OPERPSWDSALT.Value = &newsalt;\n      DERIVED_SECURTY.WRKPASSWORD.Value = Hash(&pswd);\n      DERIVED_SECURTY.PTWRKPASSWORDV1.Value = HashWithSalt(&pswd, &newsalt, \"sha1\");\n      \n      /* ICE#1560325000 Code blocks \"update versions\" and \"update password in psoprdefn\" have been moved from here down. */\n      rem put password in text to be emailed (replace any plain text and rich text targets);\n      &EMAIL_TEXT = Substitute(&RecPSPSWDEMAIL_PSWD.EMAILTEXT.Value, \"<<%PASSWORD>>\", &pswd);\n      &EMAIL_TEXT = Substitute(&EMAIL_TEXT, \"&lt;&lt;%PASSWORD&gt;&gt;\", &pswd);\n   End-If;\n   \n   \n   /* &MAIL = SendMail(0, &EMAIL_ADDRESS, \"\", \"\", \"User ID Password\", DERIVED_HINT.EMAILTEXT, \"\", \"Content-type: text/html; charset=utf8\");*/\n   /* &MAIL = SendMail(0, &EMAIL_ADDRESS, \"\", \"\", \"User ID Password\", DERIVED_HINT.EMAILTEXT, \"\", \"\", \"\", \"\", \"Content-type: text/html; charset=utf8\");*/\n   \n   Local PT_MCF_MAIL:MCFOutboundEmail &email = create PT_MCF_MAIL:MCFOutboundEmail();\n   Local PT_MCF_MAIL:MCFMultipart &mp = create PT_MCF_MAIL:MCFMultipart();\n   Local PT_MCF_MAIL:MCFMailUtil &mu = create PT_MCF_MAIL:MCFMailUtil();\n   &mp.SubType = \"related\";\n   \n   /* Please give your values for To, From and Subject */\n   &email.Recipients = &RecPSOPRDEFN.EMAILID.Value;\n   rem &email.From = \"NewPassword@DOMAIN.com\";\n   &email.Subject = MsgGetText(48, 28, \"Message not found\");\n   \n   Local array of PT_MCF_MAIL:MCFBodyPart &bp;\n   \n   /* Please give your own value for ImagesLocation a temporary place to store the image\n               This is just optional, if you do not specify it this will get copied in  PS_SERVDIR/images\n               Directory */\n   \n   rem &mu.imagesLocation = \"c:\\temp\";\n   \n   /*ParseRichTextHtml is the new function which could be used to Parse rich text.\n              Any error in this function is set in \"ErrorDescription\" property */\n   \n   &bp = &mu.ParseRichTextHtml(&EMAIL_TEXT);\n   \n   If (&bp = Null) Then\n      MessageBox(0, \"\", 0, 0, &mu.ErrorDescription);\n      Return;\n   End-If;\n   \n   &mp.AddBodyPart(&bp [1]);\n   \n   For &i = 2 To &bp.Len\n      &mp.AddBodyPart(&bp [&i]);\n   End-For;\n   \n   &email.MultiPart = &mp;\n   \n   Local integer &resp = &email.Send();\n   \n   If &resp <> %ObEmail_Delivered Then\n      &LastError = &email.ErrorDescription;\n      MessageBox(0, \"\", 0, 0, \"Message NOT Delivered\");\n      rem     MessageBox(0, \"\", 0, 0, &LastError);\n      rem     &Email_File.WriteLine(\"\");\n      rem     &Email_File.WriteLine(\"\");\n      rem     &Email_File.WriteLine(&email.ErrorDetails);\n   Else\n      MessageBox(0, \"\", 0, 0, \"Message Delivered\");\n   End-If;\n   \n   If DERIVED_HINT.HINT_RESPONSE = &RecPSUSERATTR.HINT_RESPONSE.Value And\n         (&currDateTime >= &calcDateTime) Then\n      /* ICE#1560325000 Code blocks \"update versions\" and \"update password in psoprdefn\" have been moved from above. */\n      rem update versions;\n      UpdatePSLOCK();\n      &RecPSOPRDEFN.VERSION.Value = UpdateSystemVersions();\n      &RecPSOPRDEFN.LASTPSWDCHANGE.Value = %Date;\n      &RecPSOPRDEFN.LASTUPDOPRID.Value = %UserId;\n      &RecPSOPRDEFN.LASTUPDDTTM.Value = %Datetime;\n      &RecPSOPRDEFN.Update();\n      &bUPMUpdated = True;\n   End-If;\n   \n   &RecPSUSERATTR.LASTUPDDTTM.Value = %Datetime;\n   &RecPSUSERATTR.Update();\n   \nEnd-If;\n\nDoCancel();\n";

